package com.sacco.mvp.grouplending.controller;

import com.sacco.mvp.grouplending.dto.GroupCoverageDtos.*;
import com.sacco.mvp.grouplending.service.GroupCoverageService;
import com.sacco.mvp.security.AppUserPrincipal;
import lombok.RequiredArgsConstructor;
import org.springframework.http.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.WebDataBinder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.util.*;

@Controller @RequiredArgsConstructor
public class GroupCoverageController {
    private static final String STAFF="/finance/groups/cycles/{cycle}/coverage",OWN="/app/group-coverage";
    private final GroupCoverageService coverage;
    @InitBinder("coveragePolicyForm") void policyBind(WebDataBinder b){b.setAllowedFields("requestKey","expectedPreviousId","noticeDays","caseDays","promiseDays","reference","enabled","verified");}
    @InitBinder("coverageCallForm") void callBind(WebDataBinder b){b.setAllowedFields("requestKey","sourceId","sourceKind","policyId","amount","borrowerNoticeDate","personNoticeDate","borrowerNoticeEvidence","personNoticeEvidence","noticeLanguage","noticesVerified");}
    @InitBinder("coverageResponseForm") void responseBind(WebDataBinder b,jakarta.servlet.http.HttpServletRequest request){if(request.getRequestURI().startsWith(request.getContextPath()+"/app/"))b.setAllowedFields("requestKey","expectedSequence","kind","reason","amount","promiseOn","confirmed");else b.setAllowedFields("requestKey","expectedSequence","kind","reason","confirmed");}
    @InitBinder("coverageLinkForm") void linkBind(WebDataBinder b){b.setAllowedFields("requestKey","postingId","contributionId","payerEvidence","payerVerified");}
    @InitBinder("coverageCorrectionForm") void correctionBind(WebDataBinder b){b.setAllowedFields("requestKey","reason","confirmed");}
    @ModelAttribute void privateResponse(jakarta.servlet.http.HttpServletResponse response){response.setHeader("Cache-Control","no-store");}
    private static String path(UUID cycle){return cycle==null?OWN:"/finance/groups/cycles/"+cycle+"/coverage";}
    private static void route(UUID cycle,Case c){if(cycle!=null&&!cycle.equals(c.cycle()))throw new AccessDeniedException("Coverage case unavailable");}
    private CaseContext context(AppUserPrincipal a,UUID cycle,UUID id,String action,Model m){var c=coverage.caseContext(a,id,cycle==null,action);route(cycle,c.header());m.addAttribute("caseContext",c);m.addAttribute("promiseDeadline",c.today().plusDays(c.policy().promiseDays()).isAfter(c.header().expiresOn())?c.header().expiresOn():c.today().plusDays(c.policy().promiseDays()));m.addAttribute("caseHeader",c.header());m.addAttribute("coveragePath",path(cycle));m.addAttribute("coverageStaff",cycle!=null);return c;}
    @GetMapping({STAFF,OWN}) public String list(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable(required=false) UUID cycle,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="newest") String sort,Model m){m.addAttribute("records",coverage.list(a,cycle,sort,page,cycle==null));m.addAttribute("sort",sort);m.addAttribute("coveragePath",path(cycle));m.addAttribute("coverageStaff",cycle!=null);if(cycle!=null)m.addAttribute("cycleContext",coverage.context(a,cycle));return "groups/coverage-register";}
    @GetMapping({STAFF+"/{id}",OWN+"/{id}"}) public String detail(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable(required=false) UUID cycle,@PathVariable UUID id,@RequestParam(defaultValue="0") int eventPage,@RequestParam(defaultValue="0") int paymentPage,@RequestParam(defaultValue="newest") String eventSort,@RequestParam(defaultValue="newest") String paymentSort,Model m){var data=coverage.detail(a,id,eventPage,paymentPage,eventSort,paymentSort,cycle==null);route(cycle,data.header());m.addAttribute("detail",data);m.addAttribute("actorId",a.getMemberId());m.addAttribute("responseOpen",!data.header().expiresOn().isBefore(data.today())&&!Set.of("CLOSED","CANCELLED").contains(data.header().state()));m.addAttribute("closeOpen",!Set.of("CLOSED","CANCELLED").contains(data.header().state()));m.addAttribute("caseHeader",data.header());m.addAttribute("coveragePath",path(cycle));m.addAttribute("coverageStaff",cycle!=null);m.addAttribute("eventSort",eventSort);m.addAttribute("paymentSort",paymentSort);return "groups/coverage-details";}
    @GetMapping(STAFF+"/policy") public String policy(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,Model m){coverage.authorize(a,"CONFIGURE");var f=new PolicyForm();coverage.policy(a,cycle).ifPresent(p->{f.setExpectedPreviousId(p.id());f.setNoticeDays(p.noticeDays());f.setCaseDays(p.caseDays());f.setPromiseDays(p.promiseDays());f.setReference(p.reference());f.setEnabled(p.enabled());});m.addAttribute("coveragePolicyForm",f);return policyModel(a,cycle,m);}
    private String policyModel(AppUserPrincipal a,UUID cycle,Model m){m.addAttribute("cycleContext",coverage.context(a,cycle));m.addAttribute("coveragePath",path(cycle));m.addAttribute("mode","policy");return "groups/coverage-form";}
    @PostMapping(STAFF+"/policy") public String savePolicy(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@ModelAttribute("coveragePolicyForm") PolicyForm f,BindingResult errors,Model m){coverage.authorize(a,"CONFIGURE");if(!errors.hasErrors())try{coverage.configure(a,cycle,f);return "redirect:"+path(cycle);}catch(IllegalArgumentException e){reject(errors,e,Set.of("noticeDays","caseDays","promiseDays","reference","verified"));}return policyModel(a,cycle,m);}
    @GetMapping(STAFF+"/new") public String create(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@RequestParam(defaultValue="") String choice,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,Model m){var prep=coverage.prepare(a,cycle,choice);if(prep.source()==null){m.addAttribute("choices",coverage.sourceChoices(a,cycle,search,page));m.addAttribute("search",search);m.addAttribute("coveragePath",path(cycle));m.addAttribute("cycleContext",prep.context());m.addAttribute("picker","source");return "groups/coverage-picker";}var f=new CallForm();f.setSourceId(prep.source().id());f.setSourceKind(prep.source().kind());if(prep.policy()!=null)f.setPolicyId(prep.policy().id());m.addAttribute("coverageCallForm",f);m.addAttribute("preparation",prep);m.addAttribute("coveragePath",path(cycle));m.addAttribute("mode","call");return "groups/coverage-form";}
    @PostMapping(STAFF) public String record(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@ModelAttribute("coverageCallForm") CallForm f,BindingResult errors,@RequestParam(required=false) MultipartFile noticePdf,Model m){if(!errors.hasErrors())try{return "redirect:"+path(cycle)+"/"+coverage.call(a,cycle,f,noticePdf);}catch(IllegalArgumentException e){if(key(e).endsWith("documentPdf"))m.addAttribute("noticeFileError",key(e));else reject(errors,e,Set.of("amount","borrowerNoticeDate","personNoticeDate","borrowerNoticeEvidence","personNoticeEvidence","noticeLanguage","noticesVerified"));}var prep=coverage.prepare(a,cycle,f.getSourceId()==null?"":f.getSourceKind()+":"+f.getSourceId());m.addAttribute("preparation",prep);m.addAttribute("coveragePath",path(cycle));m.addAttribute("mode","call");return "groups/coverage-form";}
    @GetMapping(OWN+"/{id}/respond") public String response(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID id,Model m){var c=context(a,null,id,"RESPOND",m);var f=new ResponseForm();f.setExpectedSequence(c.header().sequence());m.addAttribute("coverageResponseForm",f);m.addAttribute("mode","response");return "groups/coverage-form";}
    @GetMapping(STAFF+"/{id}/close") public String close(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@PathVariable UUID id,Model m){var c=context(a,cycle,id,"UPDATE",m);var f=new ResponseForm();f.setExpectedSequence(c.header().sequence());m.addAttribute("coverageResponseForm",f);m.addAttribute("mode","close");return "groups/coverage-form";}
    @PostMapping({STAFF+"/{id}/close",OWN+"/{id}/respond"}) public String respond(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable(required=false) UUID cycle,@PathVariable UUID id,@ModelAttribute("coverageResponseForm") ResponseForm f,BindingResult errors,Model m){context(a,cycle,id,cycle==null?"RESPOND":"UPDATE",m);if(!errors.hasErrors())try{if(cycle==null)coverage.respond(a,id,f);else coverage.close(a,id,f);return "redirect:"+path(cycle)+"/"+id;}catch(IllegalArgumentException e){reject(errors,e,Set.of("kind","reason","amount","promiseOn","confirmed"));}m.addAttribute("mode",cycle==null?"response":"close");return "groups/coverage-form";}
    @GetMapping(STAFF+"/{id}/link") public String link(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@PathVariable UUID id,@RequestParam(defaultValue="") String choice,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,Model m){context(a,cycle,id,"LINK",m);if(choice.isBlank()){m.addAttribute("choices",coverage.paymentChoices(a,id,search,page));m.addAttribute("search",search);m.addAttribute("picker","payment");return "groups/coverage-picker";}var key=choice.split(":",-1);if(key.length>2)throw new IllegalArgumentException("coverage.error.query");var f=new LinkForm();f.setPostingId(uuid(key[0]));if(key.length==2)f.setContributionId(uuid(key[1]));m.addAttribute("coverageLinkForm",f);m.addAttribute("paymentSource",coverage.selectedPayment(a,id,f.getPostingId(),f.getContributionId()));m.addAttribute("mode","link");return "groups/coverage-form";}
    @PostMapping(STAFF+"/{id}/link") public String saveLink(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@PathVariable UUID id,@ModelAttribute("coverageLinkForm") LinkForm f,BindingResult errors,Model m){context(a,cycle,id,"LINK",m);if(!errors.hasErrors())try{coverage.link(a,id,f);return "redirect:"+path(cycle)+"/"+id;}catch(IllegalArgumentException e){reject(errors,e,Set.of("payerEvidence","payerVerified"));}try{m.addAttribute("paymentSource",coverage.selectedPayment(a,id,f.getPostingId(),f.getContributionId()));}catch(IllegalArgumentException e){m.addAttribute("sourceUnavailable",true);}m.addAttribute("mode","link");return "groups/coverage-form";}
    @GetMapping(STAFF+"/{id}/links/{payment}/correct") public String correction(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@PathVariable UUID id,@PathVariable UUID payment,Model m){context(a,cycle,id,"REVERSE",m);m.addAttribute("paymentSource",coverage.correctionSource(a,id,payment));m.addAttribute("coverageCorrectionForm",new CorrectionForm());m.addAttribute("paymentId",payment);m.addAttribute("mode","correction");return "groups/coverage-form";}
    @PostMapping(STAFF+"/{id}/links/{payment}/correct") public String correct(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable UUID cycle,@PathVariable UUID id,@PathVariable UUID payment,@ModelAttribute("coverageCorrectionForm") CorrectionForm f,BindingResult errors,Model m){context(a,cycle,id,"REVERSE",m);if(!errors.hasErrors())try{if(!f.isConfirmed())throw new IllegalArgumentException("coverage.error.response");coverage.correct(a,id,payment,f.getRequestKey(),f.getReason());return "redirect:"+path(cycle)+"/"+id;}catch(IllegalArgumentException e){reject(errors,e,Set.of("reason","confirmed"));}m.addAttribute("paymentSource",coverage.correctionSource(a,id,payment));m.addAttribute("paymentId",payment);m.addAttribute("mode","correction");return "groups/coverage-form";}
    @GetMapping({STAFF+"/{id}/notice/{format:pdf|print}",OWN+"/{id}/notice/{format:pdf|print}"}) @ResponseBody public ResponseEntity<byte[]> notice(@AuthenticationPrincipal AppUserPrincipal a,@PathVariable(required=false) UUID cycle,@PathVariable UUID id,@PathVariable String format){var c=coverage.caseContext(a,id,cycle==null,null);route(cycle,c.header());return ResponseEntity.ok().cacheControl(CacheControl.noStore()).contentType(MediaType.APPLICATION_PDF).header("Content-Disposition",(format.equals("print")?"inline":"attachment")+"; filename=coverage-notices.pdf").header("X-Content-Type-Options","nosniff").body(coverage.notice(a,id,cycle==null));}
    @ExceptionHandler(IllegalArgumentException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) public String invalid(IllegalArgumentException e,Model m){m.addAttribute("groupError",key(e));return "groups/error";}
    private static UUID uuid(String value){try{return UUID.fromString(value);}catch(RuntimeException e){throw new IllegalArgumentException("coverage.error.query");}}
    static String key(IllegalArgumentException e){String key=Objects.toString(e.getMessage(),"");return key.matches("(?:coverage|group)[.]error[.][A-Za-z]+")?key:"coverage.error.request";}
    private static void reject(BindingResult errors,IllegalArgumentException e,Set<String> fields){String key=key(e);String field=switch(key){case "coverage.error.amount","coverage.error.shortfall","coverage.error.cap"->"amount";case "coverage.error.notice"->"noticesVerified";case "coverage.error.promise"->"promiseOn";case "coverage.error.payer"->"payerVerified";default->"";};if(fields.contains(field))errors.rejectValue(field,key);else errors.reject(key);}
}
